import{_ as o,o as a,c,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2021-07-29","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-07-29","date":"2021-07-29T00:00:00.000Z","updated":"2021-08-24T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","SMR存储技术","蓝鲸存储"],"categories":["会议纪要","存储技术"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-07-29.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-07-29.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Performance_Meeting_2021-07-29.md"};function d(t,e,r,n,s,h){return a(),c("div",null,[...e[0]||(e[0]=[l('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>PRs本周更新</strong></p><ul><li>会议主持人提出对<code>memstor</code>的重新架构，引入了<code>vector object</code>，并发现<code>buffer list</code>性能与<code>vector object</code>相当，甚至略优。</li><li><code>braddock</code>提出智能变更，允许<code>alien store</code>使用任何经典对象存储，包括<code>blue store</code>。</li><li>合并了关于设置<code>osd client message cap</code>的PR，预计能解决生产环境中与心跳超时相关的问题。</li><li><code>AVX 512 erasure coding</code>的实现因作者无法继续测试而被关闭。</li></ul></li><li><p><strong>其他技术讨论</strong></p><ul><li>讨论了<code>pg log</code>的更新，特别是关于<code>acceptable rollback info</code>的变更。</li><li><code>rgw tracing</code>优化和<code>bufferless c-string</code>处理优化正在讨论中。</li><li>进行了关于<code>finisher</code>的CPU自动释放优化的详细讨论。</li></ul></li><li><p><strong>SMR存储技术</strong></p><ul><li>讨论了<code>SMR</code>（Shingled Magnetic Recording）存储技术在<code>blue store</code>中的实现状态和未来发展方向。</li><li>目前<code>SMR</code>实现处于初级阶段，需要进一步的工作来完善功能和性能。</li><li>讨论了如何更好地支持<code>SMR</code>硬件，包括可能的硬件测试环境和模拟测试方法。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>进一步研究和优化<code>memstor</code>在写路径上的效率问题。</li><li>对<code>SMR</code>存储技术的实现进行更深入的代码审查和功能测试。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>会议主持人将重新审视<code>memstor</code>的性能问题，并尝试找出其效率低下的原因。</li><li>安排一次代码审查会议，以确定<code>SMR</code>存储技术的下一步开发方向和具体实施计划。</li><li>探索在现有测试环境中引入<code>SMR</code>硬件的可能性，以便进行更真实的性能测试。</li></ul><h4 id="其他信息" tabindex="-1">其他信息 <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息&quot;">​</a></h4><ul><li>讨论了关于<code>crimson</code>性能和效率的比较研究，特别是在小数据集和大数据集上的表现差异，以及<code>memstor</code>和<code>blue store</code>在不同场景下的效率对比。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议主要围绕Ceph存储系统的性能优化和<code>SMR</code>存储技术的实现进行了深入讨论，确定了后续的研究和开发方向。会议强调了代码审查和性能测试的重要性，并计划通过实际硬件测试来验证和优化系统性能。</p>',12)])])}const _=o(i,[["render",d]]);export{p as __pageData,_ as default};
